contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 d, uint256 a) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (d)); require(d <= 1000000000000000000000000000000);
        require(d > 0);
        require(address(this).balance >= d);

        c.deposit{value: d}(); if (__ESBMC_reverted()) return;

        uint256 cBefore = address(c).balance;

        bool withdrew;
        c.withdraw(a); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrew = false;
        } else {
            withdrew = true;
        }

        uint256 cAfter = address(c).balance;

        assert(
            (withdrew == (a <= d)) &&
            (withdrew
                ? (cBefore == cAfter + a)
                : (cBefore == cAfter))
        );
    }

    receive() external payable {}
}

